_LIT, _ANY, _CLASS, _SPLIT, _BOL, _EOL, _MATCH = range(7)


class _Parser:
    def __init__(self, pattern):
        self.pattern = pattern
        self.pos = 0
        self.length = len(pattern)

    def parse(self):
        node = self._parse_alt()
        if self.pos != self.length:
            raise ValueError("unbalanced parenthesis")
        return node

    def _parse_alt(self):
        branches = [self._parse_concat()]
        while self.pos < self.length and self.pattern[self.pos] == "|":
            self.pos += 1
            branches.append(self._parse_concat())
        if len(branches) == 1:
            return branches[0]
        return ("alt", branches)

    def _parse_concat(self):
        items = []
        pattern = self.pattern
        while self.pos < self.length:
            ch = pattern[self.pos]
            if ch == "|" or ch == ")":
                break
            if ch in "*+?":
                raise ValueError("nothing to repeat")
            atom, repeatable = self._parse_atom()
            if self.pos < self.length and pattern[self.pos] in "*+?":
                if not repeatable:
                    raise ValueError("cannot repeat an anchor")
                quant = pattern[self.pos]
                self.pos += 1
                if self.pos < self.length and pattern[self.pos] in "*+?":
                    raise ValueError("multiple repeat")
                atom = ({"*": "star", "+": "plus", "?": "opt"}[quant], atom)
            items.append(atom)
        return ("cat", items)

    def _parse_atom(self):
        pattern = self.pattern
        ch = pattern[self.pos]
        if ch == "(":
            self.pos += 1
            node = self._parse_alt()
            if self.pos >= self.length or pattern[self.pos] != ")":
                raise ValueError("missing )")
            self.pos += 1
            return node, True
        if ch == "[":
            return self._parse_class(), True
        if ch == ".":
            self.pos += 1
            return ("any",), True
        if ch == "^":
            self.pos += 1
            return ("bol",), False
        if ch == "$":
            self.pos += 1
            return ("eol",), False
        if ch == "\\":
            if self.pos + 1 >= self.length:
                raise ValueError("trailing backslash")
            self.pos += 2
            return ("lit", pattern[self.pos - 1]), True
        self.pos += 1
        return ("lit", ch), True

    def _read_class_char(self):
        pattern = self.pattern
        if self.pos >= self.length:
            raise ValueError("unterminated character set")
        ch = pattern[self.pos]
        if ch == "\\":
            if self.pos + 1 >= self.length:
                raise ValueError("trailing backslash")
            self.pos += 2
            return pattern[self.pos - 1]
        self.pos += 1
        return ch

    def _parse_class(self):
        pattern = self.pattern
        self.pos += 1
        negated = False
        if self.pos < self.length and pattern[self.pos] == "^":
            negated = True
            self.pos += 1
        ranges = []
        while True:
            if self.pos >= self.length:
                raise ValueError("unterminated character set")
            if pattern[self.pos] == "]":
                self.pos += 1
                break
            low = self._read_class_char()
            if (
                self.pos + 1 < self.length
                and pattern[self.pos] == "-"
                and pattern[self.pos + 1] != "]"
            ):
                self.pos += 1
                high = self._read_class_char()
                if low > high:
                    raise ValueError("bad character range")
                ranges.append((low, high))
            else:
                ranges.append((low, low))
        if not ranges:
            raise ValueError("empty character set")
        return ("class", negated, tuple(ranges))


class _Program:
    def __init__(self):
        self.kinds = []
        self.data = []
        self.out1 = []
        self.out2 = []

    def add(self, kind, data=None, out1=-1, out2=-1):
        self.kinds.append(kind)
        self.data.append(data)
        self.out1.append(out1)
        self.out2.append(out2)
        return len(self.kinds) - 1


def _compile(node, nxt, prog):
    tag = node[0]
    if tag == "lit":
        return prog.add(_LIT, node[1], nxt)
    if tag == "any":
        return prog.add(_ANY, None, nxt)
    if tag == "class":
        return prog.add(_CLASS, (node[1], node[2]), nxt)
    if tag == "bol":
        return prog.add(_BOL, None, nxt)
    if tag == "eol":
        return prog.add(_EOL, None, nxt)
    if tag == "cat":
        for child in reversed(node[1]):
            nxt = _compile(child, nxt, prog)
        return nxt
    if tag == "alt":
        starts = [_compile(child, nxt, prog) for child in node[1]]
        state = starts[-1]
        for begin in reversed(starts[:-1]):
            state = prog.add(_SPLIT, None, begin, state)
        return state
    if tag == "opt":
        body = _compile(node[1], nxt, prog)
        return prog.add(_SPLIT, None, body, nxt)
    if tag == "star" or tag == "plus":
        loop = prog.add(_SPLIT, None, -1, nxt)
        body = _compile(node[1], loop, prog)
        prog.out1[loop] = body
        return loop if tag == "star" else body
    raise ValueError("unknown node")


def _closure(prog, seeds, at_begin, at_end):
    kinds = prog.kinds
    out1 = prog.out1
    out2 = prog.out2
    seen = set()
    stack = list(seeds)
    consumers = []
    while stack:
        state = stack.pop()
        if state in seen:
            continue
        seen.add(state)
        kind = kinds[state]
        if kind == _SPLIT:
            stack.append(out2[state])
            stack.append(out1[state])
        elif kind == _MATCH:
            return (), True
        elif kind == _BOL:
            if at_begin:
                stack.append(out1[state])
        elif kind == _EOL:
            if at_end:
                stack.append(out1[state])
        else:
            consumers.append(state)
    consumers.sort()
    return tuple(consumers), False


def regex_search(pattern: str, text: str) -> bool:
    ast = _Parser(pattern).parse()
    prog = _Program()
    match_state = prog.add(_MATCH)
    start = _compile(ast, match_state, prog)
    length = len(text)
    current, matched = _closure(prog, [start], True, length == 0)
    if matched:
        return True
    kinds = prog.kinds
    data = prog.data
    out1 = prog.out1
    cache = {}
    for index in range(length):
        ch = text[index]
        at_end = index + 1 == length
        key = (current, ch)
        result = None if at_end else cache.get(key)
        if result is None:
            seeds = [start]
            for state in current:
                kind = kinds[state]
                if kind == _LIT:
                    ok = data[state] == ch
                elif kind == _ANY:
                    ok = True
                else:
                    negated, ranges = data[state]
                    hit = False
                    for low, high in ranges:
                        if low <= ch <= high:
                            hit = True
                            break
                    ok = hit != negated
                if ok:
                    seeds.append(out1[state])
            result = _closure(prog, seeds, False, at_end)
            if not at_end:
                if len(cache) >= 20000:
                    cache.clear()
                cache[key] = result
        current, matched = result
        if matched:
            return True
    return False
